const payload = $json || {};
const workflowName = String(payload.workflow?.name || '').trim();
const executionId = String(payload.execution?.id || '').trim();
const failedNode = String(payload.execution?.lastNodeExecuted || payload.trigger?.error?.node?.name || '').trim();
const errorMessage = String(payload.execution?.error?.message || payload.trigger?.error?.message || payload.trigger?.error?.cause?.message || '').trim().slice(0, 240);
return {
  json: {
    workflow_name: workflowName,
    execution_id: executionId,
    marker: executionId ? 'execution_id=' + executionId : '',
    failed_node: failedNode || 'unknown',
    error_message: errorMessage || 'Worker execution failed',
    is_worker_workflow: workflowName === 'RAYN Enrichment Worker'
  }
};

const context = $('Build Error Context').item.json || {};
const list = Array.isArray($json.list) ? $json.list : [];
const marker = String(context.marker || '').trim();
const matched = list.find((row) => String(row.evidence_gap || '').includes(marker));
return {
  json: {
    ...context,
    lead_id: matched?.Id || '',
  }
};
